# 3. Parse section headers
# 4. Generate HTML output

# Let me now write the Rust code

cat <<'RUSTEOF' > /workspace/elfcat_impl/src/main.rs
use std::env;
use std::fs;
use std::path::Path;

mod elf;
mod html;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 2 {
        eprintln!("Usage: elfcat <filename>");
        eprintln!("Writes <filename>.html to CWD.");
        return;
    }

    let filename = &args[1];
    let path = Path::new(filename);

    let data = match fs::read(path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("Failed to read file {:?}: {}", filename, e);
            std::process::exit(1);
        }
    };

    let elf_info = match elf::parse_elf(&data, filename) {
        Ok(e) => e,
        Err(e) => {
            eprintln!("Failed to parse ELF: {}", e);
            std::process::exit(1);
        }
    };

    let basename = path.file_name().unwrap_or_default().to_string_lossy();
    let out_filename = format!("{}.html", basename);

    let html = html::generate_html(&elf_info, filename, &data);

    match fs::write(&out_filename, html) {
        Ok(_) => {},
        Err(e) => {
            eprintln!("Failed to write {}: {}", out_filename, e);
            std::process::exit(1);
        }
    }
}
