cat <<'RUSTEOF' > /workspace/elfcat_impl/src/elf.rs
use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Bits {
    Bits32,
    Bits64,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Endian {
    Little,
    Big,
}

#[derive(Debug, Clone)]
pub struct ElfIdent {
    pub ei_class: u8,
    pub ei_data: u8,
    pub ei_version: u8,
    pub ei_osabi: u8,
    pub ei_abiversion: u8,
    pub ei_pad: [u8; 7],
}

#[derive(Debug, Clone)]
pub struct ElfHeader {
    pub ident: ElfIdent,
    pub e_type: u16,
    pub e_machine: u16,
    pub e_version: u32,
    pub e_entry: u64,
    pub e_phoff: u64,
    pub e_shoff: u64,
    pub e_flags: u32,
    pub e_ehsize: u16,
    pub e_phentsize: u16,
    pub e_phnum: u16,
    pub e_shentsize: u16,
    pub e_shnum: u16,
    pub e_shstrndx: u16,
}

#[derive(Debug, Clone)]
pub struct ProgramHeader {
    pub p_type: u32,
    pub p_flags: u32,
    pub p_offset: u64,
    pub p_vaddr: u64,
    pub p_paddr: u64,
    pub p_filesz: u64,
    pub p_memsz: u64,
    pub p_align: u64,
}

#[derive(Debug, Clone)]
pub struct SectionHeader {
    pub sh_name: u32,
    pub sh_type: u32,
    pub sh_flags: u64,
    pub sh_addr: u64,
    pub sh_offset: u64,
    pub sh_size: u64,
    pub sh_link: u32,
    pub sh_info: u32,
    pub sh_addralign: u64,
    pub sh_entsize: u64,
    pub name: String,
}

#[derive(Debug, Clone)]
pub struct NoteEntry {
    pub name: String,
    pub note_type: u32,
    pub desc: Vec<u8>,
}

#[derive(Debug, Clone)]
pub struct ElfInfo {
    pub bits: Bits,
    pub endian: Endian,
    pub header: ElfHeader,
    pub phdrs: Vec<ProgramHeader>,
    pub shdrs: Vec<SectionHeader>,
}

pub fn parse_elf(data: &[u8], _filename: &str) -> Result<ElfInfo, String> {
    if data.len() < 16 {
        return Err("file is smaller than ELF header's e_ident".to_string());
    }

    // Check magic
    if &data[0..4] != b"\x7fELF" {
        return Err("mismatched magic: not an ELF file".to_string());
    }

    let ei_class = data[4];
    let ei_data = data[5];
    let ei_version = data[6];
    let ei_osabi = data[7];
    let ei_abiversion = data[8];
    let mut ei_pad = [0u8; 7];
    ei_pad.copy_from_slice(&data[9..16]);

    let bits = match ei_class {
        1 => Bits::Bits32,
        2 => Bits::Bits64,
        _ => return Err(format!("Unknown bitness: {}", ei_class)),
    };

    let endian = match ei_data {
        1 => Endian::Little,
        2 => Endian::Big,
        _ => return Err(format!("Unknown endianness: {}", ei_data)),
    };

    let ident = ElfIdent {
        ei_class,
        ei_data,
        ei_version,
        ei_osabi,
        ei_abiversion,
        ei_pad,
    };

    let header = parse_elf_header(data, bits, endian, ident)?;

    let phdrs = if header.e_phnum > 0 && header.e_phoff > 0 {
        parse_program_headers(data, bits, endian, &header)?
    } else {
        vec![]
    };

    let shdrs = if header.e_shnum > 0 && header.e_shoff > 0 {
        parse_section_headers(data, bits, endian, &header)?
    } else {
        vec![]
    };

    Ok(ElfInfo {
        bits,
        endian,
        header,
        phdrs,
        shdrs,
    })
}

fn read_u16(data: &[u8], offset: usize, endian: Endian) -> u16 {
    match endian {
        Endian::Little => u16::from_le_bytes([data[offset], data[offset+1]]),
        Endian::Big => u16::from_be_bytes([data[offset], data[offset+1]]),
    }
}

fn read_u32(data: &[u8], offset: usize, endian: Endian) -> u32 {
    match endian {
        Endian::Little => u32::from_le_bytes([data[offset], data[offset+1], data[offset+2], data[offset+3]]),
        Endian::Big => u32::from_be_bytes([data[offset], data[offset+1], data[offset+2], data[offset+3]]),
    }
}

fn read_u64(data: &[u8], offset: usize, endian: Endian) -> u64 {
    match endian {
        Endian::Little => u64::from_le_bytes(data[offset..offset+8].try_into().unwrap()),
        Endian::Big => u64::from_be_bytes(data[offset..offset+8].try_into().unwrap()),
    }
}

fn parse_elf_header(data: &[u8], bits: Bits, endian: Endian, ident: ElfIdent) -> Result<ElfHeader, String> {
    match bits {
        Bits::Bits64 => {
            if data.len() < 64 {
                return Err("file is smaller than ELF header (64-bit)".to_string());
            }
            let e_type = read_u16(data, 16, endian);
            let e_machine = read_u16(data, 18, endian);
            let e_version = read_u32(data, 20, endian);
            let e_entry = read_u64(data, 24, endian);
            let e_phoff = read_u64(data, 32, endian);
            let e_shoff = read_u64(data, 40, endian);
            let e_flags = read_u32(data, 48, endian);
            let e_ehsize = read_u16(data, 52, endian);
            let e_phentsize = read_u16(data, 54, endian);
            let e_phnum = read_u16(data, 56, endian);
            let e_shentsize = read_u16(data, 58, endian);
            let e_shnum = read_u16(data, 60, endian);
            let e_shstrndx = read_u16(data, 62, endian);

            Ok(ElfHeader {
                ident,
                e_type,
                e_machine,
                e_version,
                e_entry,
                e_phoff,
                e_shoff,
                e_flags,
                e_ehsize,
                e_phentsize,
                e_phnum,
                e_shentsize,
                e_shnum,
                e_shstrndx,
            })
        }
        Bits::Bits32 => {
            if data.len() < 52 {
                return Err("file is smaller than ELF header (32-bit)".to_string());
            }
            let e_type = read_u16(data, 16, endian);
            let e_machine = read_u16(data, 18, endian);
            let e_version = read_u32(data, 20, endian);
            let e_entry = read_u32(data, 24, endian) as u64;
            let e_phoff = read_u32(data, 28, endian) as u64;
            let e_shoff = read_u32(data, 32, endian) as u64;
            let e_flags = read_u32(data, 36, endian);
            let e_ehsize = read_u16(data, 40, endian);
            let e_phentsize = read_u16(data, 42, endian);
            let e_phnum = read_u16(data, 44, endian);
            let e_shentsize = read_u16(data, 46, endian);
            let e_shnum = read_u16(data, 48, endian);
            let e_shstrndx = read_u16(data, 50, endian);

            Ok(ElfHeader {
                ident,
                e_type,
                e_machine,
                e_version,
                e_entry,
                e_phoff,
                e_shoff,
                e_flags,
                e_ehsize,
                e_phentsize,
                e_phnum,
                e_shentsize,
                e_shnum,
                e_shstrndx,
            })
        }
    }
}

fn parse_program_headers(data: &[u8], bits: Bits, endian: Endian, header: &ElfHeader) -> Result<Vec<ProgramHeader>, String> {
    let mut phdrs = Vec::new();
    let phoff = header.e_phoff as usize;
    let phentsize = header.e_phentsize as usize;
    let phnum = header.e_phnum as usize;

    for i in 0..phnum {
        let offset = phoff + i * phentsize;
        let phdr = match bits {
            Bits::Bits64 => {
                let p_type = read_u32(data, offset, endian);
                let p_flags = read_u32(data, offset + 4, endian);
                let p_offset = read_u64(data, offset + 8, endian);
                let p_vaddr = read_u64(data, offset + 16, endian);
                let p_paddr = read_u64(data, offset + 24, endian);
                let p_filesz = read_u64(data, offset + 32, endian);
                let p_memsz = read_u64(data, offset + 40, endian);
                let p_align = read_u64(data, offset + 48, endian);
                ProgramHeader {
                    p_type, p_flags, p_offset, p_vaddr, p_paddr,
                    p_filesz, p_memsz, p_align,
                }
            }
            Bits::Bits32 => {
                let p_type = read_u32(data, offset, endian);
                let p_offset = read_u32(data, offset + 4, endian) as u64;
                let p_vaddr = read_u32(data, offset + 8, endian) as u64;
                let p_paddr = read_u32(data, offset + 12, endian) as u64;
                let p_filesz = read_u32(data, offset + 16, endian) as u64;
                let p_memsz = read_u32(data, offset + 20, endian) as u64;
                let p_flags = read_u32(data, offset + 24, endian);
                let p_align = read_u32(data, offset + 28, endian) as u64;
                ProgramHeader {
                    p_type, p_flags, p_offset, p_vaddr, p_paddr,
                    p_filesz, p_memsz, p_align,
                }
            }
        };
        phdrs.push(phdr);
    }

    Ok(phdrs)
}

fn parse_section_headers(data: &[u8], bits: Bits, endian: Endian, header: &ElfHeader) -> Result<Vec<SectionHeader>, String> {
    let mut shdrs = Vec::new();
    let shoff = header.e_shoff as usize;
    let shentsize = header.e_shentsize as usize;
    let shnum = header.e_shnum as usize;

    // First pass: read all raw headers
    for i in 0..shnum {
        let offset = shoff + i * shentsize;
        let shdr = match bits {
            Bits::Bits64 => {
                let sh_name = read_u32(data, offset, endian);
                let sh_type = read_u32(data, offset + 4, endian);
                let sh_flags = read_u64(data, offset + 8, endian);
                let sh_addr = read_u64(data, offset + 16, endian);
                let sh_offset = read_u64(data, offset + 24, endian);
                let sh_size = read_u64(data, offset + 32, endian);
                let sh_link = read_u32(data, offset + 40, endian);
                let sh_info = read_u32(data, offset + 44, endian);
                let sh_addralign = read_u64(data, offset + 48, endian);
                let sh_entsize = read_u64(data, offset + 56, endian);
                SectionHeader {
                    sh_name, sh_type, sh_flags, sh_addr, sh_offset, sh_size,
                    sh_link, sh_info, sh_addralign, sh_entsize,
                    name: String::new(),
                }
            }
            Bits::Bits32 => {
                let sh_name = read_u32(data, offset, endian);
