pub fn parse_elf(data: &[u8], _filename: &str) -> Result<ElfInfo, String> {
    if data.len() < 16 {
        return Err("file is smaller than ELF header's e_ident".to_string());
    }

    // Check magic
    if &data[0..4] != b"\x7fELF" {
        return Err("mismatched magic: not an ELF file".to_string());
    }

    let ei_class = data[4];
    let ei_data = data[5];
    let ei_version = data[6];
    let ei_osabi = data[7];
    let ei_abiversion = data[8];
    let mut ei_pad = [0u8; 7];
    ei_pad.copy_from_slice(&data[9..16]);

    let bits = match ei_class {
        1 => Bits::Bits32,
        2 => Bits::Bits64,
        _ => return Err(format!("Unknown bitness: {}", ei_class)),
    };

    let endian = match ei_data {
        1 => Endian::Little,
        2 => Endian::Big,
        _ => return Err(format!("Unknown endianness: {}", ei_data)),
    };

    let ident = ElfIdent {
        ei_class,
        ei_data,
        ei_version,
        ei_osabi,
        ei_abiversion,
        ei_pad,
    };

    let header = parse_elf_header(data, bits, endian, ident)?;

    let phdrs = if header.e_phnum > 0 && header.e_phoff > 0 {
        parse_program_headers(data, bits, endian, &header)?
    } else {
        vec![]
    };

    let shdrs = if header.e_shnum > 0 && header.e_shoff > 0 {
        parse_section_headers(data, bits, endian, &header)?
    } else {
        vec![]
    };

    Ok(ElfInfo {
        bits,
        endian,
        header,
        phdrs,
        shdrs,
    })
}

fn read_u16(data: &[u8], offset: usize, endian: Endian) -> u16 {
    match endian {
        Endian::Little => u16::from_le_bytes([data[offset], data[offset+1]]),
        Endian::Big => u16::from_be_bytes([data[offset], data[offset+1]]),
    }
}

fn read_u32(data: &[u8], offset: usize, endian: Endian) -> u32 {
    match endian {
        Endian::Little => u32::from_le_bytes([data[offset], data[offset+1], data[offset+2], data[offset+3]]),
        Endian::Big => u32::from_be_bytes([data[offset], data[offset+1], data[offset+2], data[offset+3]]),
    }
}

fn read_u64(data: &[u8], offset: usize, endian: Endian) -> u64 {
    match endian {
        Endian::Little => u64::from_le_bytes(data[offset..offset+8].try_into().unwrap()),
        Endian::Big => u64::from_be_bytes(data[offset..offset+8].try_into().unwrap()),
    }
}

fn parse_elf_header(data: &[u8], bits: Bits, endian: Endian, ident: ElfIdent) -> Result<ElfHeader, String> {
    match bits {
        Bits::Bits64 => {
            if data.len() < 64 {
                return Err("file is smaller than ELF header (64-bit)".to_string());
            }
            let e_type = read_u16(data, 16, endian);
            let e_machine = read_u16(data, 18, endian);
            let e_version = read_u32(data, 20, endian);
            let e_entry = read_u64(data, 24, endian);
            let e_phoff = read_u64(data, 32, endian);
            let e_shoff = read_u64(data, 40, endian);
            let e_flags = read_u32(data, 48, endian);
            let e_ehsize = read_u16(data, 52, endian);
            let e_phentsize = read_u16(data, 54, endian);
            let e_phnum = read_u16(data, 56, endian);
            let e_shentsize = read_u16(data, 58, endian);
            let e_shnum = read_u16(data, 60, endian);
            let e_shstrndx = read_u16(data, 62, endian);

            Ok(ElfHeader {
                ident,
                e_type,
                e_machine,
                e_version,
                e_entry,
                e_phoff,
                e_shoff,
                e_flags,
                e_ehsize,
                e_phentsize,
                e_phnum,
                e_shentsize,
                e_shnum,
                e_shstrndx,
            })
        }
        Bits::Bits32 => {
            if data.len() < 52 {
                return Err("file is smaller than ELF header (32-bit)".to_string());
            }
            let e_type = read_u16(data, 16, endian);
            let e_machine = read_u16(data, 18, endian);
            let e_version = read_u32(data, 20, endian);
            let e_entry = read_u32(data, 24, endian) as u64;
            let e_phoff = read_u32(data, 28, endian) as u64;
            let e_shoff = read_u32(data, 32, endian) as u64;
            let e_flags = read_u32(data, 36, endian);
            let e_ehsize = read_u16(data, 40, endian);
            let e_phentsize = read_u16(data, 42, endian);
            let e_phnum = read_u16(data, 44, endian);
            let e_shentsize = read_u16(data, 46, endian);
            let e_shnum = read_u16(data, 48, endian);
            let e_shstrndx = read_u16(data, 50, endian);

            Ok(ElfHeader {
