                e_shnum,
                e_shstrndx,
            })
        }
    }
}

fn parse_program_headers(data: &[u8], bits: Bits, endian: Endian, header: &ElfHeader) -> Result<Vec<ProgramHeader>, String> {
    let mut phdrs = Vec::new();
    let phoff = header.e_phoff as usize;
    let phentsize = header.e_phentsize as usize;
    let phnum = header.e_phnum as usize;

    for i in 0..phnum {
        let offset = phoff + i * phentsize;
        let phdr = match bits {
            Bits::Bits64 => {
                let p_type = read_u32(data, offset, endian);
                let p_flags = read_u32(data, offset + 4, endian);
                let p_offset = read_u64(data, offset + 8, endian);
                let p_vaddr = read_u64(data, offset + 16, endian);
                let p_paddr = read_u64(data, offset + 24, endian);
                let p_filesz = read_u64(data, offset + 32, endian);
                let p_memsz = read_u64(data, offset + 40, endian);
                let p_align = read_u64(data, offset + 48, endian);
                ProgramHeader {
                    p_type, p_flags, p_offset, p_vaddr, p_paddr,
                    p_filesz, p_memsz, p_align,
                }
            }
            Bits::Bits32 => {
                let p_type = read_u32(data, offset, endian);
                let p_offset = read_u32(data, offset + 4, endian) as u64;
                let p_vaddr = read_u32(data, offset + 8, endian) as u64;
                let p_paddr = read_u32(data, offset + 12, endian) as u64;
                let p_filesz = read_u32(data, offset + 16, endian) as u64;
                let p_memsz = read_u32(data, offset + 20, endian) as u64;
                let p_flags = read_u32(data, offset + 24, endian);
                let p_align = read_u32(data, offset + 28, endian) as u64;
                ProgramHeader {
                    p_type, p_flags, p_offset, p_vaddr, p_paddr,
                    p_filesz, p_memsz, p_align,
                }
            }
        };
        phdrs.push(phdr);
    }

    Ok(phdrs)
}

fn parse_section_headers(data: &[u8], bits: Bits, endian: Endian, header: &ElfHeader) -> Result<Vec<SectionHeader>, String> {
    let mut shdrs = Vec::new();
    let shoff = header.e_shoff as usize;
    let shentsize = header.e_shentsize as usize;
    let shnum = header.e_shnum as usize;

    // First pass: read all raw headers
    for i in 0..shnum {
        let offset = shoff + i * shentsize;
        let shdr = match bits {
            Bits::Bits64 => {
                let sh_name = read_u32(data, offset, endian);
                let sh_type = read_u32(data, offset + 4, endian);
                let sh_flags = read_u64(data, offset + 8, endian);
                let sh_addr = read_u64(data, offset + 16, endian);
                let sh_offset = read_u64(data, offset + 24, endian);
                let sh_size = read_u64(data, offset + 32, endian);
                let sh_link = read_u32(data, offset + 40, endian);
                let sh_info = read_u32(data, offset + 44, endian);
                let sh_addralign = read_u64(data, offset + 48, endian);
                let sh_entsize = read_u64(data, offset + 56, endian);
                SectionHeader {
                    sh_name, sh_type, sh_flags, sh_addr, sh_offset, sh_size,
                    sh_link, sh_info, sh_addralign, sh_entsize,
                    name: String::new(),
                }
            }
            Bits::Bits32 => {
                let sh_name = read_u32(data, offset, endian);
                let sh_type = read_u32(data, offset + 4, endian);
                let sh_flags = read_u32(data, offset + 8, endian) as u64;
                let sh_addr = read_u32(data, offset + 12, endian) as u64;
                let sh_offset = read_u32(data, offset + 16, endian) as u64;
                let sh_size = read_u32(data, offset + 20, endian) as u64;
                let sh_link = read_u32(data, offset + 24, endian);
                let sh_info = read_u32(data, offset + 28, endian);
                let sh_addralign = read_u32(data, offset + 32, endian) as u64;
                let sh_entsize = read_u32(data, offset + 36, endian) as u64;
                SectionHeader {
                    sh_name, sh_type, sh_flags, sh_addr, sh_offset, sh_size,
                    sh_link, sh_info, sh_addralign, sh_entsize,
                    name: String::new(),
                }
            }
        };
        shdrs.push(shdr);
    }

    // Resolve section names using shstrtab
    let shstrndx = header.e_shstrndx as usize;
    if shstrndx < shdrs.len() {
        let strtab_offset = shdrs[shstrndx].sh_offset as usize;
        let strtab_size = shdrs[shstrndx].sh_size as usize;
        if strtab_offset + strtab_size <= data.len() {
            let strtab = &data[strtab_offset..strtab_offset + strtab_size];
            for shdr in shdrs.iter_mut() {
                let name_offset = shdr.sh_name as usize;
                if name_offset < strtab.len() {
                    let end = strtab[name_offset..].iter().position(|&b| b == 0).unwrap_or(strtab.len() - name_offset);
                    shdr.name = String::from_utf8_lossy(&strtab[name_offset..name_offset + end]).to_string();
                }
            }
        }
    }

    Ok(shdrs)
}

