pub fn parse_notes(data: &[u8], offset: usize, size: usize, endian: Endian) -> Vec<NoteEntry> {
    let mut notes = Vec::new();
    let end = offset + size;
    let mut pos = offset;

    while pos + 12 <= end {
        let namesz = match endian {
            Endian::Little => u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]) as usize,
            Endian::Big => u32::from_be_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]) as usize,
        };
        let descsz = match endian {
            Endian::Little => u32::from_le_bytes([data[pos+4], data[pos+5], data[pos+6], data[pos+7]]) as usize,
            Endian::Big => u32::from_be_bytes([data[pos+4], data[pos+5], data[pos+6], data[pos+7]]) as usize,
        };
        let note_type = match endian {
            Endian::Little => u32::from_le_bytes([data[pos+8], data[pos+9], data[pos+10], data[pos+11]]),
            Endian::Big => u32::from_be_bytes([data[pos+8], data[pos+9], data[pos+10], data[pos+11]]),
        };

        pos += 12;

        // Read name
        let name_start = pos;
        let name_end = std::cmp::min(pos + namesz, data.len());
        let name_bytes = &data[name_start..name_end];
        // Name is null-terminated
        let name_len = name_bytes.iter().position(|&b| b == 0).unwrap_or(namesz);
        let name = String::from_utf8_lossy(&name_bytes[..name_len]).to_string();

        // Align to 4 bytes
        let name_padded = (namesz + 3) & !3;
        pos += name_padded;

        // Read desc
        let desc_start = pos;
        let desc_end = std::cmp::min(pos + descsz, data.len());
        let desc = data[desc_start..desc_end].to_vec();

        // Align to 4 bytes
        let desc_padded = (descsz + 3) & !3;
        pos += desc_padded;

        notes.push(NoteEntry { name, note_type, desc });
    }

    notes
}

pub fn read_cstring(data: &[u8], offset: usize) -> String {
    if offset >= data.len() {
        return String::new();
    }
    let end = data[offset..].iter().position(|&b| b == 0).unwrap_or(data.len() - offset);
    String::from_utf8_lossy(&data[offset..offset+end]).to_string()
}

pub fn read_strtab_strings(data: &[u8], offset: usize, size: usize) -> Vec<String> {
    if offset >= data.len() || size == 0 {
        return vec![];
    }
    let end = std::cmp::min(offset + size, data.len());
    let strtab = &data[offset..end];

    let mut strings = Vec::new();
    let mut i = 0;
    while i < strtab.len() {
        let start = i;
        while i < strtab.len() && strtab[i] != 0 {
            i += 1;
        }
        let s = String::from_utf8_lossy(&strtab[start..i]).to_string();
        if !s.is_empty() {
            strings.push(s);
        }
        i += 1; // skip null terminator
    }

    strings
}
