      function showIfMatches(cl, prefix, newPrefix, indirect = false) {
          if (!cl.startsWith(prefix)) {
              return;
          }

          let tableId = cl.replace(prefix, newPrefix);
          let table = document.getElementById(tableId);

          if (table === null) {
              return;
          }

          table.style.display = "block";

