fn generate_bytes(info: &ElfInfo, data: &[u8]) -> String {
    let mut out = String::from("    <div id='bytes'>");

    // Build the list of structural annotations for the bytes
    let annotations = build_annotations(info, data);

    // Render bytes with annotations
    render_bytes(&mut out, data, &annotations);

    out.push_str("</div>\n");
