#[derive(Clone, Debug)]
struct ByteAnnotation {
    offset: usize,
    end: usize,
    class: String,         // CSS class for this span
    field_name: Option<String>,  // Sub-field name if this is a field within a structure
    is_segment: bool,
    is_section: bool,
    is_phdr: bool,
    is_shdr: bool,
    is_ehdr: bool,
    segment_subrange: bool,  // wrap content in segment_subrange
}

fn build_annotations(info: &ElfInfo, data: &[u8]) -> Vec<ByteAnnotation> {
    let mut anns: Vec<ByteAnnotation> = Vec::new();
    let hdr = &info.header;
    let bits = info.bits;
    let file_len = data.len();

    let ehdr_size = match bits {
        Bits::Bits64 => 64usize,
        Bits::Bits32 => 52usize,
    };

    // ELF header annotation (large span)
    if ehdr_size <= file_len {
        anns.push(ByteAnnotation {
            offset: 0,
            end: ehdr_size,
            class: "ehdr".to_string(),
            field_name: None,
            is_segment: false, is_section: false, is_phdr: false, is_shdr: false, is_ehdr: true,
            segment_subrange: false,
        });
    }

    // Program header annotations
    let phoff = hdr.e_phoff as usize;
    let phentsize = hdr.e_phentsize as usize;
    for (i, _phdr) in info.phdrs.iter().enumerate() {
        let start = phoff + i * phentsize;
        let end = start + phentsize;
        if end <= file_len {
            anns.push(ByteAnnotation {
                offset: start,
                end,
                class: format!("bin_phdr{} phdr", i),
                field_name: None,
                is_segment: false, is_section: false, is_phdr: true, is_shdr: false, is_ehdr: false,
                segment_subrange: false,
            });
        }
    }

    // Section header annotations
    let shoff = hdr.e_shoff as usize;
    let shentsize = hdr.e_shentsize as usize;
    for (j, _shdr) in info.shdrs.iter().enumerate() {
        let start = shoff + j * shentsize;
        let end = start + shentsize;
        if end <= file_len {
            anns.push(ByteAnnotation {
                offset: start,
                end,
                class: format!("bin_shdr{} shdr", j),
                field_name: None,
                is_segment: false, is_section: false, is_phdr: false, is_shdr: true, is_ehdr: false,
                segment_subrange: false,
            });
        }
    }

    // Segment annotations (only if p_offset > 0 and p_filesz > 0)
    for (i, phdr) in info.phdrs.iter().enumerate() {
        if phdr.p_offset > 0 && phdr.p_filesz > 0 {
            let start = phdr.p_offset as usize;
            let end = start + phdr.p_filesz as usize;
            let end = end.min(file_len);
            if start < file_len {
                anns.push(ByteAnnotation {
                    offset: start,
                    end,
                    class: format!("bin_segment{} segment", i),
                    field_name: None,
                    is_segment: true, is_section: false, is_phdr: false, is_shdr: false, is_ehdr: false,
                    segment_subrange: false,
                });
            }
        }
    }

    // Section annotations (only if sh_type != NULL/NOBITS and sh_size > 0)
    // Determine which sections are inside NOTE segments
    let note_segment_ranges: Vec<(usize, usize)> = info.phdrs.iter()
        .filter(|p| p.p_type == 4 && p.p_offset > 0 && p.p_filesz > 0) // PT_NOTE
        .map(|p| (p.p_offset as usize, (p.p_offset + p.p_filesz) as usize))
        .collect();

    for (j, shdr) in info.shdrs.iter().enumerate() {
        if shdr.sh_type == 0 || shdr.sh_type == 8 { // NULL or NOBITS
            continue;
        }
        if shdr.sh_size == 0 {
            continue;
        }
        let start = shdr.sh_offset as usize;
        let end = start + shdr.sh_size as usize;
        let end = end.min(file_len);
        if start >= file_len {
            continue;
        }

        // Check if this section is inside a NOTE segment
        let in_note_segment = note_segment_ranges.iter().any(|&(ns, ne)| {
            start >= ns && end <= ne
        });

        anns.push(ByteAnnotation {
            offset: start,
            end,
            class: format!("bin_section{} section hover", j),
            field_name: None,
            is_segment: false, is_section: true, is_phdr: false, is_shdr: false, is_ehdr: false,
            segment_subrange: in_note_segment,
        });
    }

    anns
}

