use crate::elf::*;

pub fn generate_html(info: &ElfInfo, filename: &str, data: &[u8]) -> String {
    let mut out = String::new();

    let basename = std::path::Path::new(filename)
        .file_name()
        .unwrap_or_default()
        .to_string_lossy()
        .to_string();
    // Remove .html suffix from title if any  
