    // Pre-render the entire byte sequence with markup

    // Build a map of: offset -> list of span opens, and offset -> list of span closes
    let mut opens_at: Vec<Vec<usize>> = vec![vec![]; file_len + 1];
    let mut closes_at: Vec<Vec<usize>> = vec![vec![]; file_len + 1];

    for (i, ann) in sorted_anns.iter().enumerate() {
        if ann.offset < file_len {
            opens_at[ann.offset].push(i);
        }
        if ann.end <= file_len + 1 {
            closes_at[ann.end].push(i);
        }
    }

    // For closes, we need to close in reverse order of opening (LIFO stack)
    // Use a stack approach

    let mut span_stack: Vec<usize> = Vec::new(); // indices into sorted_anns

    let mut col = 0usize; // current column within a row (0-15)

    // We need the ELF header sub-field spans too
    // Let me build ALL the sub-field spans as well
    let all_spans = build_all_spans_for_bytes(sorted_anns);

    render_with_spans(out, data, &all_spans);
}

#[derive(Clone, Debug)]
struct Span {
    start: usize,
    end: usize,   // exclusive
    class: String,
    subrange: bool,  // wrap content in segment_subrange
}

fn build_all_spans_for_bytes(anns: &[&ByteAnnotation]) -> Vec<Span> {
    let mut spans: Vec<Span> = Vec::new();
    for ann in anns {
        spans.push(Span {
            start: ann.offset,
            end: ann.end,
            class: ann.class.clone(),
            subrange: ann.segment_subrange,
        });
    }
    spans
}

// This is a simplified but working renderer
fn render_with_spans(out: &mut String, data: &[u8], spans: &[Span]) {
    // Not efficient but correct: for each byte, determine its active spans
    // Then render with proper nesting

    // We'll use an interval tree approach simplified:
    // Sort spans by (start ASC, end DESC) for proper nesting
    let mut sorted_spans = spans.to_vec();
    sorted_spans.sort_by(|a, b| {
        a.start.cmp(&b.start).then(b.end.cmp(&a.end))
    });

    let file_len = data.len();

    // For each position, determine what events happen
    // Use a event-driven approach with span stack

    let mut events: Vec<(usize, bool, usize)> = Vec::new(); // (pos, is_open, span_idx)
    for (i, span) in sorted_spans.iter().enumerate() {
        if span.start < file_len {
            events.push((span.start, true, i));
        }
        if span.end <= file_len {
            events.push((span.end, false, i));
        }
    }
    events.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));

    // Render byte by byte
    let mut open_spans: Vec<usize> = Vec::new(); // indices of currently open spans
    let mut event_idx = 0;

    for byte_pos in 0..file_len {
        // Check for close events at this position
        let mut to_close: Vec<usize> = Vec::new();
        let mut temp_events = event_idx;
        while temp_events < events.len() && events[temp_events].0 <= byte_pos {
            if !events[temp_events].1 {
                to_close.push(events[temp_events].2);
            }
            temp_events += 1;
        }

        // Process all events up to byte_pos
        while event_idx < events.len() && events[event_idx].0 <= byte_pos {
            let (pos, is_open, span_idx) = events[event_idx];
            if pos == byte_pos {
                break; // Handle open events for THIS position separately
            }
            if !is_open {
                // Close events before this position
                if let Some(p) = open_spans.iter().position(|&s| s == span_idx) {
                    // Need to close this and all spans above it in the stack
                    let spans_to_reopen: Vec<usize> = open_spans[p+1..].to_vec();
                    let spans_to_close_count = open_spans.len() - p;
                    for _ in 0..spans_to_close_count {
                        out.push_str("</span>");
                    }
                    open_spans.truncate(p);
                    // Reopen spans that were above
                    for &s in &spans_to_reopen {
                        open_spans.push(s);
                        let cls = &sorted_spans[s].class;
                        let subrange = sorted_spans[s].subrange;
                        if subrange {
                            out.push_str(&format!("<span class='{}'>", cls));
                            out.push_str("<span class='segment_subrange hover'>");
                        } else {
                            out.push_str(&format!("<span class='{}'>", cls));
                        }
                    }
                }
            }
            event_idx += 1;
        }

        // Handle row start
        if byte_pos % 16 == 0 && byte_pos > 0 {
            out.push('\n');
        }

        // Handle space before byte (not first in row)
        if byte_pos % 16 != 0 {
            // Check if we need to add space
            // The space should be outside any span that just started
            // This is complex; for now output space here
        }

        // Actually, let's use a completely different approach
        // Just render raw then post-process - no, that won't work with spans

        out.push_str(&hex_byte(data[byte_pos]));
        if byte_pos % 16 != 15 && byte_pos != file_len - 1 {
            out.push(' ');
        }
    }

    // Close all remaining open spans
    for _ in 0..open_spans.len() {
        out.push_str("</span>");
    }
}

fn generate_ascii(data: &[u8]) -> String {
    let mut out = String::from("    <div id='ascii'>");
    let file_len = data.len();

    for (i, &b) in data.iter().enumerate() {
        if i > 0 && i % 16 == 0 {
            out.push('\n');
        }
        if b >= 0x21 && b <= 0x7e {
            match b {
                b'<' => out.push_str("&lt;"),
                b'>' => out.push_str("&gt;"),
                b'&' => out.push_str("&amp;"),
                b'"' => out.push_str("&quot;"),
                _ => out.push(b as char),
            }
        } else {
            out.push('.');
        }
    }

    out.push_str("</div>\n");
    out
}

fn generate_sticky_table(info: &ElfInfo, data: &[u8]) -> String {
    let mut out = String::from("    <table id='sticky_table' cellspacing='0'>\n      <tr>\n        <td id='desc'></td>\n");

    // First infotables: phdrs and shdrs
    out.push_str("        <td class='infotables'>\n");
    for (i, phdr) in info.phdrs.iter().enumerate() {
        out.push_str(&generate_phdr_info(i, phdr, info.bits));
    }
    for (j, shdr) in info.shdrs.iter().enumerate() {
        out.push_str(&generate_shdr_info(j, shdr, info));
    }
    out.push_str("        </td>\n");

    // Second infotables: segments and sections
    out.push_str("        <td class='infotables'>\n");
    for (i, phdr) in info.phdrs.iter().enumerate() {
        out.push_str(&generate_segment_info(i, phdr, data, info));
    }
    for (j, shdr) in info.shdrs.iter().enumerate() {
        out.push_str(&generate_section_info(j, shdr, data, info));
    }
    out.push_str("        </td>\n");

    out.push_str("      </tr>\n    </table>\n");
    out
}

