fn html_escape(s: &str) -> String {
    s.replace('&', "&amp;")
     .replace('<', "&lt;")
     .replace('>', "&gt;")
     .replace('"', "&quot;")
}

fn generate_segment_info(idx: usize, phdr: &ProgramHeader, data: &[u8], info: &ElfInfo) -> String {
    let type_name = get_segment_type_name(phdr.p_type);
    let mut s = format!(
        "          <table class='conceal itable' id='info_segment{}'>\n          <th colspan='2' class='segment_itable'></th>\n            <tr> <td>Type:</td> <td>{}</td> </tr>\n            <tr> <td>Size in file:</td> <td>{}</td> </tr>\n            <tr> <td>Size in memory:</td> <td>{}</td> </tr>\n",
        idx, type_name,
        span_size(phdr.p_filesz),
        span_size(phdr.p_memsz),
    );

    // Additional info based on segment type
    match phdr.p_type {
        3 => { // PT_INTERP
            let offset = phdr.p_offset as usize;
            let size = phdr.p_filesz as usize;
            if offset + size <= data.len() {
                let interp = read_cstring(data, offset);
                s.push_str("            <tr><td><br></td></tr>\n");
                s.push_str(&format!("            <tr> <td>Interpreter:</td> <td>{}</td> </tr>\n", html_escape(&interp)));
            }
        }
        4 => { // PT_NOTE
            // Parse notes from all PT_NOTE segments
            let all_notes = collect_all_notes(info, data);
            if !all_notes.is_empty() {
                s.push_str("            <tr><td><br></td></tr>\n");
                for note in &all_notes {
                    s.push_str(&format_note_html(note));
                }
            }
        }
        _ => {}
    }

    s.push_str("          </table>\n");
    s
}

fn collect_all_notes(info: &ElfInfo, data: &[u8]) -> Vec<NoteEntry> {
    let mut all_notes = Vec::new();
    for phdr in &info.phdrs {
        if phdr.p_type == 4 && phdr.p_offset > 0 && phdr.p_filesz > 0 {
            let offset = phdr.p_offset as usize;
            let size = phdr.p_filesz as usize;
            let notes = parse_notes(data, offset, size, info.endian);
            all_notes.extend(notes);
        }
    }
    all_notes
}

fn format_note_html(note: &NoteEntry) -> String {
    let mut s = String::new();
    s.push_str(&format!("            <tr> <td>Name:</td> <td>{}</td> </tr>\n", html_escape(&note.name)));

    // Check for special GNU note types
    if note.name == "GNU" && note.note_type == 3 {
        // NT_GNU_BUILD_ID
        s.push_str(&format!("            <tr> <td>Type:</td> <td>{:#x}</td> </tr>\n", note.note_type));
        let build_id: String = note.desc.iter().map(|b| format!("{:02x}", b)).collect();
        s.push_str(&format!("            <tr> <td>Build ID:</td> <td>{}</td> </tr>\n", build_id));
    } else {
        s.push_str(&format!("            <tr> <td>Type:</td> <td>{:#x}</td> </tr>\n", note.note_type));
        s.push_str("            <tr> <td>Desc:</td> <td>");
        for &b in &note.desc {
            if b >= 0x21 && b <= 0x7e {
                s.push(b as char); // No HTML escaping! (original bug behavior)
            } else {
                s.push_str(&format!("<b>{:02x}</b> ", b));
            }
        }
        s.push_str("</td> </tr>\n");
    }
    s.push_str("            <tr> <td><br></td> </tr>\n");
    s
}

fn generate_section_info(idx: usize, shdr: &SectionHeader, data: &[u8], info: &ElfInfo) -> String {
    let type_name = get_section_type_name(shdr.sh_type);
    let mut s = format!(
        "          <table class='conceal itable' id='info_section{}'>\n          <th colspan='2' class='section_itable'></th>\n            <tr> <td>Type:</td> <td>{}</td> </tr>\n            <tr> <td>Size:</td> <td>{}</td> </tr>\n",
        idx, type_name,
        span_size(shdr.sh_size),
    );

    // For STRTAB sections, show string contents
    if shdr.sh_type == 3 && shdr.sh_size > 0 { // SHT_STRTAB
        let offset = shdr.sh_offset as usize;
        let size = shdr.sh_size as usize;
        let strings = read_strtab_strings(data, offset, size);
        if !strings.is_empty() {
            s.push_str("            <tr><td><br></td></tr>\n");
            s.push_str("            <tr>\n              <td></td>\n              <td>\n                <div>\n");
            for string in &strings {
                s.push_str("                  ");
                s.push_str(&html_escape(string));
                s.push('\n');
            }
            s.push_str("                </div>\n              </td>\n            </tr>\n");
        }
    }

    s.push_str("          </table>\n");
    s
}

