          let target = event.target || event.srcElement;
          let parents = listOfParents(target);
          let cleared = false;
          const prefix = 'bin_';

          for (let i = 0; i < parents.length; i++) {
              let cl = parents[i];

              if (!cl.startsWith(prefix)) {
                  continue;
              }

              if (!cleared) {
                  cleared = true;
                  hidePreviousTables();
              }

              showIfMatches(cl, prefix, "info_");
              showIfMatches(cl, "bin_segment", "info_phdr", true);
