fn generate_header(title: &str) -> String {
    format!(include_str!("header_template.html"), title = title)
}

fn format_filesize(size: usize) -> String {
    if size >= 1024 * 1024 * 1024 {
        format!("{:.1} GiB ({} B)", (size as f64) / (1024.0 * 1024.0 * 1024.0), size)
    } else if size >= 1024 * 1024 {
        format!("{:.1} MiB ({} B)", (size as f64) / (1024.0 * 1024.0), size)
    } else if size >= 1024 {
        format!("{:.1} KiB ({} B)", (size as f64) / 1024.0, size)
    } else {
        format!("{} B", size)
    }
}

fn format_size_inner(size: u64) -> String {
    if size >= 1024 {
        let kib = size as f64 / 1024.0;
        let rounded = (kib * 10.0).round() / 10.0;
        format!("{} ({:.1} KiB)", size, rounded)
    } else {
        format!("{}", size)
    }
}

fn span_addr(value: u64) -> String {
