use crate::elf::*;

pub fn generate_html(info: &ElfInfo, filename: &str, data: &[u8]) -> String {
    let mut out = String::new();

    let basename = std::path::Path::new(filename)
        .file_name()
        .unwrap_or_default()
        .to_string_lossy()
        .to_string();
    let title = basename.clone();

    out.push_str(&generate_header(&title));
    out.push_str(&generate_fileinfo(info, filename, data));
    out.push_str(&generate_offsets(data.len()));
    out.push_str(&generate_bytes(info, data));
    out.push_str(&generate_ascii(data));
    out.push_str(&generate_sticky_table(info, data));
    out.push_str(&generate_scripts(info, data));
    out.push_str("  </body>\n</html>\n");

    out
}

fn generate_header(title: &str) -> String {
    format!(include_str!("header_template.html"), title = title)
}

fn format_filesize(size: usize) -> String {
    if size >= 1024 * 1024 * 1024 {
        format!("{:.1} GiB ({} B)", (size as f64) / (1024.0 * 1024.0 * 1024.0), size)
    } else if size >= 1024 * 1024 {
        format!("{:.1} MiB ({} B)", (size as f64) / (1024.0 * 1024.0), size)
    } else if size >= 1024 {
        format!("{:.1} KiB ({} B)", (size as f64) / 1024.0, size)
    } else {
        format!("{} B", size)
    }
}

fn format_size_inner(size: u64) -> String {
    if size >= 1024 {
        let kib = size as f64 / 1024.0;
        let rounded = (kib * 10.0).round() / 10.0;
        format!("{} ({:.1} KiB)", size, rounded)
    } else {
        format!("{}", size)
    }
}

fn span_addr(value: u64) -> String {
    format!("<span class='number' title='{}'>{:#x}</span>", value, value)
}

fn span_size(value: u64) -> String {
    format!("<span class='number' title='{:#x}'>{}</span>", value, format_size_inner(value))
}

fn span_count(value: u64) -> String {
    format!("<span class='number' title='{:#x}'>{}</span>", value, value)
}

fn html_escape(s: &str) -> String {
    s.replace('&', "&amp;")
     .replace('<', "&lt;")
     .replace('>', "&gt;")
     .replace('"', "&quot;")
}

fn generate_fileinfo(info: &ElfInfo, filename: &str, data: &[u8]) -> String {
    let hdr = &info.header;

    let class_str = match info.bits {
        Bits::Bits32 => "32-bit",
        Bits::Bits64 => "64-bit",
    };

    let data_str = match info.endian {
        Endian::Little => "Little endian",
        Endian::Big => "Big endian",
    };

    let osabi = hdr.ident.ei_osabi;
    let abi_name = get_abi_name(osabi);
    let (abi_label, abi_value) = if is_uncommon_abi(osabi) {
        let name = if abi_name.is_empty() {
            format!("Unknown: {}", osabi)
        } else {
            abi_name.to_string()
        };
        ("Uncommon ABI(!):", name)
    } else {
        ("ABI:", abi_name.to_string())
    };

    let type_str = get_elf_type_name(hdr.e_type);
    let machine_str = get_machine_name(hdr.e_machine);
    let filesize = format_filesize(data.len());

    let phnum_span = format!("<span title='{:#x}' class='number fileinfo_e_phnum'>{}</span>", hdr.e_phnum, hdr.e_phnum);
    let phentsize_span = format!("<span title='{:#x}' class='number fileinfo_e_phentsize'>{}</span>", hdr.e_phentsize, hdr.e_phentsize);
    let phoff_span = format!("<span title='{:#x}' class='number fileinfo_e_phoff'>{}</span>", hdr.e_phoff, hdr.e_phoff);
    let shnum_span = format!("<span title='{:#x}' class='number fileinfo_e_shnum'>{}</span>", hdr.e_shnum, hdr.e_shnum);
    let shentsize_span = format!("<span title='{:#x}' class='number fileinfo_e_shentsize'>{}</span>", hdr.e_shentsize, hdr.e_shentsize);
    let shoff_span = format!("<span title='{:#x}' class='number fileinfo_e_shoff'>{}</span>", hdr.e_shoff, hdr.e_shoff);

    format!("    <table>\n      <tr class='fileinfo_file_name'> <td>File name:</td> <td>{}</td> </tr>\n      <tr class='fileinfo_file_size'> <td>File size:</td> <td>{}</td> </tr>\n      <tr class='fileinfo_class'> <td>Object class:</td> <td>{}</td> </tr>\n      <tr class='fileinfo_data'> <td>Data encoding:</td> <td>{}</td> </tr>\n      <tr class='fileinfo_abi'> <td>{}:</td> <td>{}</td> </tr>\n      <tr class='fileinfo_e_type'> <td>Type:</td> <td>{}</td> </tr>\n      <tr class='fileinfo_e_machine'> <td>Architecture:</td> <td>{}</td> </tr>\n      <tr class='fileinfo_e_entry'> <td>Entrypoint:</td> <td>{}</td> </tr>\n      <tr class='fileinfo_ph'> <td>Program headers:</td> <td>{} * {} @ {}</td> </tr>\n      <tr class='fileinfo_sh'> <td>Section headers:</td> <td>{} * {} @ {}</td> </tr>\n    </table>\n",
        filename, filesize, class_str, data_str,
        abi_label, abi_value, type_str, machine_str,
        span_addr(hdr.e_entry),
        phnum_span, phentsize_span, phoff_span,
        shnum_span, shentsize_span, shoff_span,
    )
}

fn generate_offsets(file_len: usize) -> String {
    let columns = 16usize;
    let rows = (file_len + columns - 1) / columns;
    let mut s = String::from("    <div id='offsets'>");
    for i in 0..rows {
        if i > 0 { s.push('\n'); }
        s.push_str(&format!("{:x}", i * columns));
    }
    s.push_str("</div>\n");
    s
}

// A span to render in the bytes section
#[derive(Clone, Debug)]
struct ByteSpan {
    start: usize,
    end: usize,   // exclusive
    open_tag: String,
    close_tag: String,
    // For sub-spans within this span (field names like p_type, p_flags, etc.)
    sub_spans: Vec<ByteSpan>,
}

impl ByteSpan {
    fn new(start: usize, end: usize, class: &str) -> Self {
        ByteSpan {
            start, end,
            open_tag: format!("<span class='{}'>", class),
            close_tag: "</span>".to_string(),
            sub_spans: vec![],
        }
    }
}

fn generate_bytes(info: &ElfInfo, data: &[u8]) -> String {
    let mut out = String::from("    <div id='bytes'>");

    let spans = build_byte_spans(info, data);
    render_byte_spans(&mut out, data, &spans);

    out.push_str("</div>\n");
    out
}

fn build_byte_spans(info: &ElfInfo, data: &[u8]) -> Vec<ByteSpan> {
    let hdr = &info.header;
    let bits = info.bits;
    let file_len = data.len();
    let endian = info.endian;

    let ehdr_size = if bits == Bits::Bits64 { 64usize } else { 52usize };

    let mut spans: Vec<ByteSpan> = Vec::new();

    // 1. ELF header span with sub-spans
    if ehdr_size <= file_len {
        let mut ehdr_span = ByteSpan::new(0, ehdr_size, "ehdr");

        // ident sub-span
        let mut ident_span = ByteSpan::new(0, 16, "ident");
        ident_span.sub_spans.push(ByteSpan::new(0, 4, "magic"));
        ident_span.sub_spans.push(ByteSpan::new(4, 5, "class"));
        ident_span.sub_spans.push(ByteSpan::new(5, 6, "data"));
        ident_span.sub_spans.push(ByteSpan::new(6, 7, "ver"));
        ident_span.sub_spans.push(ByteSpan::new(7, 8, "abi"));
        ident_span.sub_spans.push(ByteSpan::new(8, 9, "abi_ver"));
        ident_span.sub_spans.push(ByteSpan::new(9, 16, "pad"));
        ehdr_span.sub_spans.push(ident_span);

        match bits {
            Bits::Bits64 => {
                ehdr_span.sub_spans.push(ByteSpan::new(16, 18, "e_type"));
                ehdr_span.sub_spans.push(ByteSpan::new(18, 20, "e_machine"));
                ehdr_span.sub_spans.push(ByteSpan::new(20, 24, "e_version"));
                ehdr_span.sub_spans.push(ByteSpan::new(24, 32, "e_entry"));
                ehdr_span.sub_spans.push(ByteSpan::new(32, 40, "e_phoff"));
                ehdr_span.sub_spans.push(ByteSpan::new(40, 48, "e_shoff"));
                ehdr_span.sub_spans.push(ByteSpan::new(48, 52, "e_flags"));
                ehdr_span.sub_spans.push(ByteSpan::new(52, 54, "e_ehsize"));
                ehdr_span.sub_spans.push(ByteSpan::new(54, 56, "e_phentsize"));
                ehdr_span.sub_spans.push(ByteSpan::new(56, 58, "e_phnum"));
                ehdr_span.sub_spans.push(ByteSpan::new(58, 60, "e_shentsize"));
                ehdr_span.sub_spans.push(ByteSpan::new(60, 62, "e_shnum"));
                ehdr_span.sub_spans.push(ByteSpan::new(62, 64, "e_shstrndx"));
            }
            Bits::Bits32 => {
                ehdr_span.sub_spans.push(ByteSpan::new(16, 18, "e_type"));
                ehdr_span.sub_spans.push(ByteSpan::new(18, 20, "e_machine"));
                ehdr_span.sub_spans.push(ByteSpan::new(20, 24, "e_version"));
                ehdr_span.sub_spans.push(ByteSpan::new(24, 28, "e_entry"));
                ehdr_span.sub_spans.push(ByteSpan::new(28, 32, "e_phoff"));
                ehdr_span.sub_spans.push(ByteSpan::new(32, 36, "e_shoff"));
                ehdr_span.sub_spans.push(ByteSpan::new(36, 40, "e_flags"));
                ehdr_span.sub_spans.push(ByteSpan::new(40, 42, "e_ehsize"));
                ehdr_span.sub_spans.push(ByteSpan::new(42, 44, "e_phentsize"));
                ehdr_span.sub_spans.push(ByteSpan::new(44, 46, "e_phnum"));
                ehdr_span.sub_spans.push(ByteSpan::new(46, 48, "e_shentsize"));
                ehdr_span.sub_spans.push(ByteSpan::new(48, 50, "e_shnum"));
                ehdr_span.sub_spans.push(ByteSpan::new(50, 52, "e_shstrndx"));
            }
        }

        spans.push(ehdr_span);
    }

    // 2. Segment spans (only if p_offset > 0 and p_filesz > 0)
    for (i, phdr) in info.phdrs.iter().enumerate() {
        if phdr.p_offset > 0 && phdr.p_filesz > 0 {
            let start = phdr.p_offset as usize;
            let end = (start + phdr.p_filesz as usize).min(file_len);
            if start < file_len {
                spans.push(ByteSpan::new(start, end, &format!("bin_segment{} segment", i)));
            }
        }
    }

    // 3. Program header spans (with sub-field spans)
    let phoff = hdr.e_phoff as usize;
    let phentsize = hdr.e_phentsize as usize;
    for (i, _phdr) in info.phdrs.iter().enumerate() {
        let start = phoff + i * phentsize;
        let end = start + phentsize;
        if end <= file_len {
            let mut phdr_span = ByteSpan::new(start, end, &format!("bin_phdr{} phdr", i));
            match bits {
                Bits::Bits64 => {
                    phdr_span.sub_spans.push(ByteSpan::new(start, start+4, "p_type"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+4, start+8, "p_flags"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+8, start+16, "p_offset"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+16, start+24, "p_vaddr"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+24, start+32, "p_paddr"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+32, start+40, "p_filesz"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+40, start+48, "p_memsz"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+48, start+56, "p_align"));
                }
                Bits::Bits32 => {
                    phdr_span.sub_spans.push(ByteSpan::new(start, start+4, "p_type"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+4, start+8, "p_offset"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+8, start+12, "p_vaddr"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+12, start+16, "p_paddr"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+16, start+20, "p_filesz"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+20, start+24, "p_memsz"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+24, start+28, "p_flags"));
                    phdr_span.sub_spans.push(ByteSpan::new(start+28, start+32, "p_align"));
                }
            }
            spans.push(phdr_span);
        }
    }

    // 4. Section spans
    // Determine which sections are inside PT_NOTE segments
    let note_segment_ranges: Vec<(usize, usize)> = info.phdrs.iter()
        .filter(|p| p.p_type == 4 && p.p_offset > 0 && p.p_filesz > 0)
        .map(|p| (p.p_offset as usize, (p.p_offset + p.p_filesz) as usize))
        .collect();

    for (j, shdr) in info.shdrs.iter().enumerate() {
        if shdr.sh_type == 0 || shdr.sh_type == 8 || shdr.sh_size == 0 {
            continue;
        }
        let start = shdr.sh_offset as usize;
        let end = (start + shdr.sh_size as usize).min(file_len);
        if start >= file_len { continue; }

        let in_note = note_segment_ranges.iter().any(|&(ns, ne)| start >= ns && end <= ne);

        let mut sec_span = ByteSpan::new(start, end, &format!("bin_section{} section hover", j));
        if in_note {
            // Wrap entire section content in segment_subrange
            let mut sub = ByteSpan::new(start, end, "segment_subrange hover");
            sub.open_tag = "<span class='segment_subrange hover'>".to_string();
            sec_span.sub_spans.push(sub);
        }
        spans.push(sec_span);
    }

    // 5. Section header spans (with sub-field spans)
    let shoff = hdr.e_shoff as usize;
    let shentsize = hdr.e_shentsize as usize;
    for (j, _shdr) in info.shdrs.iter().enumerate() {
        let start = shoff + j * shentsize;
        let end = start + shentsize;
        if end <= file_len {
            let mut shdr_span = ByteSpan::new(start, end, &format!("bin_shdr{} shdr", j));
            match bits {
                Bits::Bits64 => {
                    shdr_span.sub_spans.push(ByteSpan::new(start, start+4, "sh_name"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+4, start+8, "sh_type"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+8, start+16, "sh_flags"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+16, start+24, "sh_addr"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+24, start+32, "sh_offset"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+32, start+40, "sh_size"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+40, start+44, "sh_link"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+44, start+48, "sh_info"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+48, start+56, "sh_addralign"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+56, start+64, "sh_entsize"));
                }
                Bits::Bits32 => {
                    shdr_span.sub_spans.push(ByteSpan::new(start, start+4, "sh_name"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+4, start+8, "sh_type"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+8, start+12, "sh_flags"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+12, start+16, "sh_addr"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+16, start+20, "sh_offset"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+20, start+24, "sh_size"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+24, start+28, "sh_link"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+28, start+32, "sh_info"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+32, start+36, "sh_addralign"));
                    shdr_span.sub_spans.push(ByteSpan::new(start+36, start+40, "sh_entsize"));
                }
            }
            spans.push(shdr_span);
        }
    }

    spans
}

// Flatten all spans (including sub-spans) into a sorted list of (start, end, open_tag, is_open)
// Returns list of events
#[derive(Clone, Debug)]
enum Event {
    Open { pos: usize, end: usize, tag: String, span_id: usize },
    Close { pos: usize, span_id: usize },
}

fn flatten_spans(spans: &[ByteSpan]) -> Vec<ByteSpan> {
    let mut flat = Vec::new();
    for span in spans {
        flat.push(ByteSpan {
            start: span.start,
            end: span.end,
            open_tag: span.open_tag.clone(),
            close_tag: span.close_tag.clone(),
            sub_spans: vec![],
        });
        flat.extend(flatten_spans(&span.sub_spans));
    }
    flat
}

fn render_byte_spans(out: &mut String, data: &[u8], spans: &[ByteSpan]) {
    // Flatten all spans including sub-spans
    let flat = flatten_spans(spans);

    // Sort by (start ASC, end DESC) for proper containment-based nesting
    let mut sorted: Vec<ByteSpan> = flat;
    sorted.sort_by(|a, b| a.start.cmp(&b.start).then(b.end.cmp(&a.end)));

    let file_len = data.len();

    // Use a stack-based renderer
    // At each byte position, we may have spans opening and closing

    // For each position, record which spans start and end
    // spans_start[pos] = list of span indices (in sorted order)
    // spans_end[pos] = list of span indices

    // We use a stack; when a span "ends" before the current position,
    // we pop from stack and close+reopen as needed

    // Actually, with proper nesting (guaranteed by our sort), we can use a simple stack:
    // - When we reach span.start: push onto stack and emit open_tag
    // - When we've passed span.end: close that span (and any inner spans, reopen inner ones)

    // Let's use a different approach: interval-based rendering with a "current stack" 
    // that we update lazily

    let mut stack: Vec<usize> = Vec::new(); // indices into sorted
    let mut byte_pos = 0usize;

    while byte_pos < file_len {
        // 1. Close spans that ended at or before byte_pos
        // These should be at top of stack (innermost first)
        loop {
            let top = match stack.last() {
                Some(&top) => top,
                None => break,
            };
            if sorted[top].end <= byte_pos {
                // Close this span
                out.push_str(&sorted[top].close_tag);
                stack.pop();
            } else {
                break;
            }
        }

        // 2. Open spans that start at byte_pos
        // Find all spans starting at byte_pos
        let mut new_spans: Vec<usize> = sorted.iter().enumerate()
            .filter(|(_, s)| s.start == byte_pos && s.end > byte_pos)
            .map(|(i, _)| i)
            .collect();
        // Already sorted by (start ASC, end DESC) = outer first

        for &idx in &new_spans {
            out.push_str(&sorted[idx].open_tag);
            stack.push(idx);
        }

        // 3. Emit byte
        if byte_pos % 16 != 0 {
            out.push(' ');
        } else if byte_pos > 0 {
            out.push('\n');
        }

        // Format byte: special handling for magic bytes (first 4 bytes)
        if byte_pos < 4 {
            let b = data[byte_pos];
            if b >= 0x21 && b <= 0x7e {
                // Printable: render as &nbsp;X
                out.push_str("&nbsp;");
                out.push(b as char);
            } else {
                out.push_str(&format!("{:02x}", b));
            }
        } else {
            out.push_str(&format!("{:02x}", data[byte_pos]));
        }

        byte_pos += 1;
    }

    // Close remaining spans
    while let Some(idx) = stack.pop() {
        out.push_str(&sorted[idx].close_tag);
    }
}

fn generate_ascii(data: &[u8]) -> String {
    let mut out = String::from("    <div id='ascii'>");

    for (i, &b) in data.iter().enumerate() {
        if i > 0 && i % 16 == 0 {
            out.push('\n');
        }
        if b >= 0x21 && b <= 0x7e {
            match b {
                b'<' => out.push_str("&lt;"),
                b'>' => out.push_str("&gt;"),
                b'&' => out.push_str("&amp;"),
                b'"' => out.push_str("&quot;"),
                _ => out.push(b as char),
            }
        } else {
            out.push('.');
        }
    }

    out.push_str("</div>\n");
    out
}

fn generate_sticky_table(info: &ElfInfo, data: &[u8]) -> String {
    let mut out = String::from("    <table id='sticky_table' cellspacing='0'>\n      <tr>\n        <td id='desc'></td>\n");

    out.push_str("        <td class='infotables'>\n");
    for (i, phdr) in info.phdrs.iter().enumerate() {
        out.push_str(&generate_phdr_info(i, phdr));
    }
    for (j, shdr) in info.shdrs.iter().enumerate() {
        out.push_str(&generate_shdr_info(j, shdr));
    }
    out.push_str("        </td>\n");

    out.push_str("        <td class='infotables'>\n");
    for (i, phdr) in info.phdrs.iter().enumerate() {
        out.push_str(&generate_segment_info(i, phdr, data, info));
    }
    for (j, shdr) in info.shdrs.iter().enumerate() {
        out.push_str(&generate_section_info(j, shdr, data, info));
    }
    out.push_str("        </td>\n");

    out.push_str("      </tr>\n    </table>\n");
    out
}

fn generate_phdr_info(idx: usize, phdr: &ProgramHeader) -> String {
    let type_name = get_segment_type_name(phdr.p_type);
    let flags = get_segment_flags(phdr.p_flags);

    format!(
        "          <table class='conceal itable' id='info_phdr{}'>\n          <th colspan='2' class='phdr_itable'></th>\n            <tr> <td>Type:</td> <td>{}</td> </tr>\n            <tr> <td>Flags:</td> <td>{}</td> </tr>\n            <tr> <td>Offset in file:</td> <td>{}</td> </tr>\n            <tr> <td>Size in file:</td> <td>{}</td> </tr>\n            <tr> <td>Vaddr in memory:</td> <td>{}</td> </tr>\n            <tr> <td>Size in memory:</td> <td>{}</td> </tr>\n            <tr> <td>Alignment:</td> <td>{}</td> </tr>\n          </table>\n",
        idx, type_name, flags,
        span_addr(phdr.p_offset), span_size(phdr.p_filesz),
        span_addr(phdr.p_vaddr), span_size(phdr.p_memsz),
        span_addr(phdr.p_align),
    )
}

fn generate_shdr_info(idx: usize, shdr: &SectionHeader) -> String {
    let type_name = get_section_type_name(shdr.sh_type);
    let flags = get_section_flags(shdr.sh_flags);

    format!(
        "          <table class='conceal itable' id='info_shdr{}'>\n          <th colspan='2' class='shdr_itable'></th>\n            <tr> <td>Index:</td> <td>{}</td> </tr>\n            <tr> <td>Name:</td> <td>{}</td> </tr>\n            <tr> <td>Type:</td> <td>{}</td> </tr>\n            <tr> <td>Flags:</td> <td>{}</td> </tr>\n            <tr> <td>Vaddr in memory:</td> <td>{}</td> </tr>\n            <tr> <td>Offset in file:</td> <td>{}</td> </tr>\n            <tr> <td>Size in file:</td> <td>{}</td> </tr>\n            <tr> <td>Linked section:</td> <td>{}</td> </tr>\n            <tr> <td>Extra info:</td> <td>{}</td> </tr>\n            <tr> <td>Alignment:</td> <td>{}</td> </tr>\n            <tr> <td>Size of entries:</td> <td>{}</td> </tr>\n          </table>\n",
        idx, idx,
        html_escape(&shdr.name), type_name, flags,
        span_addr(shdr.sh_addr), span_addr(shdr.sh_offset),
        span_size(shdr.sh_size), shdr.sh_link,
        span_count(shdr.sh_info as u64),
        span_addr(shdr.sh_addralign),
        span_count(shdr.sh_entsize),
    )
}

fn generate_segment_info(idx: usize, phdr: &ProgramHeader, data: &[u8], info: &ElfInfo) -> String {
    let type_name = get_segment_type_name(phdr.p_type);
    let mut s = format!(
        "          <table class='conceal itable' id='info_segment{}'>\n          <th colspan='2' class='segment_itable'></th>\n            <tr> <td>Type:</td> <td>{}</td> </tr>\n            <tr> <td>Size in file:</td> <td>{}</td> </tr>\n            <tr> <td>Size in memory:</td> <td>{}</td> </tr>\n",
        idx, type_name,
        span_size(phdr.p_filesz), span_size(phdr.p_memsz),
    );

    match phdr.p_type {
        3 => { // PT_INTERP
            let offset = phdr.p_offset as usize;
            let size = phdr.p_filesz as usize;
            if offset + size <= data.len() {
                let interp = read_cstring(data, offset);
                s.push_str("            <tr><td><br></td></tr>\n");
                s.push_str(&format!("            <tr> <td>Interpreter:</td> <td>{}</td> </tr>\n", html_escape(&interp)));
            }
        }
        4 => { // PT_NOTE
            let all_notes = collect_all_notes(info, data);
            if !all_notes.is_empty() {
                s.push_str("            <tr><td><br></td></tr>\n");
                for note in &all_notes {
                    s.push_str(&format_note_html(note));
                }
            }
        }
        _ => {}
    }

    s.push_str("          </table>\n");
    s
}

fn collect_all_notes(info: &ElfInfo, data: &[u8]) -> Vec<NoteEntry> {
    let mut all_notes = Vec::new();
    for phdr in &info.phdrs {
        if phdr.p_type == 4 && phdr.p_offset > 0 && phdr.p_filesz > 0 {
            let offset = phdr.p_offset as usize;
            let size = phdr.p_filesz as usize;
            let notes = parse_notes(data, offset, size, info.endian);
            all_notes.extend(notes);
        }
    }
    all_notes
}

fn format_note_html(note: &NoteEntry) -> String {
    let mut s = String::new();
    s.push_str(&format!("            <tr> <td>Name:</td> <td>{}</td> </tr>\n", html_escape(&note.name)));

    if note.name == "GNU" && note.note_type == 3 {
        s.push_str(&format!("            <tr> <td>Type:</td> <td>{:#x}</td> </tr>\n", note.note_type));
        let build_id: String = note.desc.iter().map(|b| format!("{:02x}", b)).collect();
        s.push_str(&format!("            <tr> <td>Build ID:</td> <td>{}</td> </tr>\n", build_id));
    } else {
        s.push_str(&format!("            <tr> <td>Type:</td> <td>{:#x}</td> </tr>\n", note.note_type));
        s.push_str("            <tr> <td>Desc:</td> <td>");
        for &b in &note.desc {
            if b >= 0x21 && b <= 0x7e {
                s.push(b as char);
            } else {
                s.push_str(&format!("<b>{:02x}</b> ", b));
            }
        }
        s.push_str("</td> </tr>\n");
    }
    s.push_str("            <tr> <td><br></td> </tr>\n");
    s
}

fn generate_section_info(idx: usize, shdr: &SectionHeader, data: &[u8], _info: &ElfInfo) -> String {
    let type_name = get_section_type_name(shdr.sh_type);
    let mut s = format!(
        "          <table class='conceal itable' id='info_section{}'>\n          <th colspan='2' class='section_itable'></th>\n            <tr> <td>Type:</td> <td>{}</td> </tr>\n            <tr> <td>Size:</td> <td>{}</td> </tr>\n",
        idx, type_name, span_size(shdr.sh_size),
    );

    // For STRTAB sections, show string contents
    if shdr.sh_type == 3 && shdr.sh_size > 0 {
        let offset = shdr.sh_offset as usize;
        let size = shdr.sh_size as usize;
        let strings = read_strtab_strings(data, offset, size);
        if !strings.is_empty() {
            s.push_str("            <tr><td><br></td></tr>\n");
            s.push_str("            <tr>\n              <td></td>\n              <td>\n                <div>\n");
            for string in &strings {
                s.push_str("                  ");
                s.push_str(&html_escape(string));
                s.push('\n');
            }
            s.push_str("                </div>\n              </td>\n            </tr>\n");
        }
    }

    s.push_str("          </table>\n");
    s
}

