        eprintln!("Writes <filename>.html to CWD.");
        return;
    }

    let filename = &args[1];
    let path = Path::new(filename);

    let data = match fs::read(path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("Failed to read file {:?}: {}", filename, e);
            std::process::exit(1);
        }
    };

    let elf_info = match elf::parse_elf(&data, filename) {
        Ok(e) => e,
        Err(e) => {
            eprintln!("Failed to parse ELF: {}", e);
            std::process::exit(1);
        }
    };

    let basename = path.file_name().unwrap_or_default().to_string_lossy();
    let out_filename = format!("{}.html", basename);

    let html_content = html::generate_html(&elf_info, filename, &data);

    match fs::write(&out_filename, html_content) {
        Ok(_) => {},
        Err(e) => {
            eprintln!("Failed to write {}: {}", out_filename, e);
            std::process::exit(1);
        }
    }
}
