        if i > 0 && i % 16 == 0 {
            out.push(\'\\n\');
        }
        if b >= 0x21 && b <= 0x7e {
            match b {
                b\'<\' => out.push_str("&lt;"),
                b\'>\' => out.push_str("&gt;"),
                b\'&\' => out.push_str("&amp;"),
                b\'"\' => out.push_str("&quot;"),
                b\'\\\'\' => out.push_str("&apos;"),
