    let mut out = String::from("    <div id='ascii'>");
    let file_len = data.len();

    for (i, &b) in data.iter().enumerate() {
        if b >= 0x21 && b <= 0x7e {
            match b {
                b'<' => out.push_str("&lt;"),
                b'>' => out.push_str("&gt;"),
                b'&' => out.push_str("&amp;"),
                b'"' => out.push_str("&quot;"),
                b'\'' => out.push_str("&apos;"),
                _ => out.push(b as char),
            }
        } else {
            out.push('.');
        }
        // After each complete row, add newline (but not after the very last byte)
        if (i + 1) % 16 == 0 && i + 1 < file_len {
            out.push('\n');
        }
    }

    out.push_str("</div>\n");
    out
}'''

