# In nonnote.elf: segment0 directly contains segment_subrange (no sections in between)
# The segment_subrange wraps ALL bytes within the PT_NOTE segment

# For hello.elf with sections:
# segment7 (PT_NOTE) -> section2 (NOTE section) -> segment_subrange -> bytes

# The difference is that when there are sections, they wrap the content first
# When there are no sections, the content goes directly into segment_subrange

# To implement this correctly:
# For each PT_NOTE segment (p_type == 4):
#   - If it has sections within it: those sections' CONTENT get segment_subrange
#   - If it has NO sections: add a segment_subrange span that covers the entire segment

# My current approach: add segment_subrange as a sub-span of sections that are in NOTE segments
# 
# NEW approach: 
# 1. For sections within NOTE segments: keep current behavior (segment_subrange inside section)
# 2. For NOTE segments WITHOUT any sections: add segment_subrange directly inside the segment

# But wait - looking at the code, the `sub_spans` structure...
# The segment span is a ByteSpan with no sub_spans currently
# The section span has sub_spans containing the segment_subrange

# For nonnote.elf: I need to add segment_subrange INSIDE the segment span (not inside a section)
# This means the segment ByteSpan needs a sub_span that is a segment_subrange

# Let me fix build_byte_spans to handle this case:
# For each PT_NOTE segment, check if it has any sections
# If NO sections: add segment_subrange as a sub_span of the segment span

python3 << 'PYEOF'
with open('/workspace/elfcat_impl/src/html.rs', 'r') as f:
    content = f.read()

# Find the segment spans section in build_byte_spans
old_segment_code = '''    // 2. Segment spans (only if p_offset > 0 and p_filesz > 0)
    for (i, phdr) in info.phdrs.iter().enumerate() {
        if phdr.p_offset > 0 && phdr.p_filesz > 0 {
            let start = phdr.p_offset as usize;
            let end = (start + phdr.p_filesz as usize).min(file_len);
            if start < file_len {
                spans.push(ByteSpan::new(start, end, &format!("bin_segment{} segment", i)));
            }
        }
    }'''

new_segment_code = '''    // 2. Segment spans (only if p_offset > 0 and p_filesz > 0)
    // Determine which sections are inside each segment for segment_subrange logic
    let section_ranges: Vec<(usize, usize)> = info.shdrs.iter()
        .filter(|s| s.sh_type != 0 && s.sh_type != 8 && s.sh_size > 0)
        .map(|s| (s.sh_offset as usize, (s.sh_offset + s.sh_size) as usize))
        .collect();

    for (i, phdr) in info.phdrs.iter().enumerate() {
        if phdr.p_offset > 0 && phdr.p_filesz > 0 {
            let start = phdr.p_offset as usize;
            let end = (start + phdr.p_filesz as usize).min(file_len);
            if start < file_len {
                let mut seg_span = ByteSpan::new(start, end, &format!("bin_segment{} segment", i));
                // For PT_NOTE segments without any sections inside: add segment_subrange directly
                if phdr.p_type == 4 {
                    let has_sections = section_ranges.iter().any(|&(ss, se)| ss >= start && se <= end);
                    if !has_sections {
                        seg_span.sub_spans.push(ByteSpan::new(start, end, "segment_subrange hover"));
                    }
                }
                spans.push(seg_span);
            }
        }
    }'''

if old_segment_code in content:
    content = content.replace(old_segment_code, new_segment_code)
    print("Fixed segment spans")
else:
    print("Not found!")
    idx = content.find('// 2. Segment spans')
    if idx >= 0:
        print(repr(content[idx:idx+300]))

