python3 << 'PYEOF'
with open('/workspace/elfcat_impl/src/html.rs', 'r') as f:
    content = f.read()

fn_start = content.find('fn render_byte_spans(out: &mut String, data: &[u8], spans: &[ByteSpan]) {')
fn_end = content.find('\nfn ', fn_start + 10)

new_fn = r'''fn render_byte_spans(out: &mut String, data: &[u8], spans: &[ByteSpan]) {
    let flat = flatten_spans(spans);
    let mut sorted: Vec<ByteSpan> = flat;
    sorted.sort_by(|a, b| a.start.cmp(&b.start).then(b.end.cmp(&a.end)));

    let file_len = data.len();

    // For each byte, compute the list of active spans sorted by containment
    // Use a stack to track currently open spans (indices into sorted)
    let mut open_stack: Vec<usize> = Vec::new();

    for byte_pos in 0..file_len {
        // Compute the desired span stack for this position
        let mut desired: Vec<usize> = sorted.iter().enumerate()
            .filter(|(_, s)| s.start <= byte_pos && s.end > byte_pos)
            .map(|(i, _)| i)
            .collect();
        // desired is already sorted by (start ASC, end DESC) from the sorted vector

        // Find how many spans are in common (prefix)
        let common = open_stack.iter().zip(desired.iter())
            .take_while(|(a, b)| a == b)
            .count();

        // Close spans from open_stack that are not in desired (from deepest outward)
        let to_close = open_stack.len() - common;
        // Close inner spans first
        for _ in 0..to_close {
            out.push_str("</span>");
        }
        open_stack.truncate(common);

        // Output separator (AFTER closing spans, BEFORE opening new ones)
        if byte_pos % 16 == 0 {
            if byte_pos > 0 {
                out.push('\n');
            }
        } else {
            out.push(' ');
        }

        // Open new spans (from common onwards)
        for i in common..desired.len() {
            let span_idx = desired[i];
            out.push_str(&sorted[span_idx].open_tag);
        }
        open_stack = desired;

        // Output the byte
        if byte_pos < 4 {
            let b = data[byte_pos];
            if b >= 0x21 && b <= 0x7e {
                out.push_str("&nbsp;");
                out.push(b as char);
            } else {
                out.push_str(&format!("{:02x}", b));
            }
        } else {
            out.push_str(&format!("{:02x}", data[byte_pos]));
        }
    }

    // Close remaining spans
    for _ in 0..open_stack.len() {
        out.push_str("</span>");
    }
}'''

